function model(p) {
  // 12 learners: practice hours vs assessment score (seeded synthetic data with a clear upward trend), plus one outlier.
  let s = 7;
  const rnd = () => { s |= 0; s = s + 0x6D2B79F5 | 0; let t = Math.imul(s ^ s >>> 15, 1 | s); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const points = Array.from({ length: 12 }, (_, i) => { const x = i + 1; return { x, y: +(34 + 4.3 * x + (rnd() - 0.5) * 12).toFixed(1) }; });
  const outlier = { x: 13, y: Math.max(0, Math.min(100, +p.outlierY)), included: Math.round(p.include) === 1 };
  const fitOf = pts => {
    const n = pts.length, mx = pts.reduce((a, q) => a + q.x, 0) / n, my = pts.reduce((a, q) => a + q.y, 0) / n;
    let sxy = 0, sxx = 0; for (const q of pts) { sxy += (q.x - mx) * (q.y - my); sxx += (q.x - mx) ** 2; }
    const slope = sxy / sxx, intercept = my - slope * mx;
    return { slope, intercept };
  };
  const sseOf = (pts, b, a) => pts.reduce((acc, q) => acc + (q.y - (a + b * q.x)) ** 2, 0);
  const clean = fitOf(points);
  const used = outlier.included ? points.concat([outlier]) : points;
  const fit = fitOf(used);
  const residuals = used.map((q, i) => { const yhat = fit.intercept + fit.slope * q.x, r = q.y - yhat; return { x: q.x, y: q.y, yhat, r, r2: r * r, isOutlier: i === 12 }; });
  const sse = residuals.reduce((a, q) => a + q.r2, 0);
  const oldLineSSE = sseOf(used, clean.slope, clean.intercept);
  const outlierShare = outlier.included ? residuals[12].r2 / sse : 0;
  const fmt = v => Math.round(v).toLocaleString('en-US');
  const duration = 12, markers = [0, 2, 4, 5.5, 8, 11];
  const summary = outlier.included
    ? 'One outlier moves the slope from ' + clean.slope.toFixed(1) + ' to ' + fit.slope.toFixed(1) + ' points per hour; its square is ' + Math.round(outlierShare * 100) + '% of the total squared error (' + fmt(sse) + ', versus ' + fmt(oldLineSSE) + ' for the old line).'
    : 'Without the outlier the line keeps a slope of ' + clean.slope.toFixed(1) + ' points per hour; total squared error ' + fmt(sse) + ' over 12 points.';
  return {
    points, outlier, clean: { slope: clean.slope, intercept: clean.intercept, sse: sseOf(points, clean.slope, clean.intercept) },
    fit: { slope: fit.slope, intercept: fit.intercept, sse }, residuals, oldLineSSE, outlierShare, n: used.length,
    xDomain: [0, 14], yDomain: [0, 100],
    phases: { points: [0, 2], clean: [2, 4], outlier: [4, 5.5], refit: [5.5, 8], squares: [8, 11] },
    duration, markers, summary
  };
}

checkCode:
function check(p) {
  const m = model(p), pts = m.outlier.included ? m.points.concat([m.outlier]) : m.points, n = pts.length;
  // Closed form via the normal equations: [n Sx; Sx Sxx] [a; b] = [Sy; Sxy]
  let Sx = 0, Sy = 0, Sxx = 0, Sxy = 0; for (const q of pts) { Sx += q.x; Sy += q.y; Sxx += q.x * q.x; Sxy += q.x * q.y; }
  const det = n * Sxx - Sx * Sx, b = (n * Sxy - Sx * Sy) / det, a = (Sy * Sxx - Sx * Sxy) / det;
  const sse = (bb, aa) => pts.reduce((acc, q) => acc + (q.y - aa - bb * q.x) ** 2, 0);
  const base = sse(m.fit.slope, m.fit.intercept);
  const nudges = [];
  for (const db of [-0.05, 0, 0.05]) for (const da of [-0.5, 0, 0.5]) if (db || da) nudges.push(sse(m.fit.slope + db, m.fit.intercept + da));
  const closed = Math.abs(b - m.fit.slope) < 1e-9 && Math.abs(a - m.fit.intercept) < 1e-9 && Math.abs(base - m.fit.sse) < 1e-6;
  const lowest = nudges.every(v => v > base), minN = Math.min(...nudges);
  return {
    pass: closed && lowest,
    detail: 'Slope ' + m.fit.slope.toFixed(3) + ' and intercept ' + m.fit.intercept.toFixed(2) + ' match the closed-form solution (' + b.toFixed(3) + ', ' + a.toFixed(2) + '); total squared error ' +
      base.toFixed(1) + ' is below all 8 nudged lines (smallest ' + minN.toFixed(1) + ').'
  };
}
